 static void PumpUntil(Func<bool> predicate){var frame=new System.Windows.Threading.DispatcherFrame();var watch=System.Diagnostics.Stopwatch.StartNew();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(15)};timer.Tick+=(s,e)=>{if(predicate()||watch.Elapsed>TimeSpan.FromSeconds(10))frame.Continue=false;};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);timer.Stop();if(!predicate())throw new TimeoutException("Import response did not arrive.");}
 static void Render(Window window,string file){window.UpdateLayout();var content=(FrameworkElement)window.Content;int width=(int)Math.Ceiling(content.ActualWidth),height=(int)Math.Ceiling(content.ActualHeight);var drawing=new DrawingVisual();using(var context=drawing.RenderOpen()){context.DrawRectangle(window.Background,null,new Rect(0,0,width,height));context.DrawRectangle(new VisualBrush(content),null,new Rect(0,0,width,height));}var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(file))encoder.Save(stream);}
